// Thin wrapper around angular-html-parser. Normalises the result into our
// own node shapes so the rest of the pipeline doesn't depend on the
// parser's internal classes. Throws on any parse error (caller catches and
// returns source unchanged per ADR-0010).

import { parse as parseHtml } from 'angular-html-parser'

export function parseMaskedHtml(masked) {
  const result = parseHtml(masked, {
    canSelfClose: true,
    allowHtmComponentClosingTags: true,
    isTagNameCaseSensitive: false,
  })
  if (result.errors && result.errors.length > 0) {
    const e = result.errors[0]
    const where = e.span?.start ? `${e.span.start.line + 1}:${e.span.start.col + 1}` : ''
    throw new Error(`angular-html-parser error at ${where}: ${e.msg ?? e}`)
  }
  return result.rootNodes.map((n) => convertNode(n, masked))
}

function convertNode(node, source) {
  if (node.kind === 'text' || node.kind === 'cdata') {
    // angular-html-parser decodes HTML entities into Unicode. To
    // round-trip we need the original source bytes — losing `&amp;` →
    // `&` breaks attribute URLs and lets `Tom & Jerry <3` reparse as a
    // bogus tag opener on the next pass.
    let value = node.value
    if (node.sourceSpan) {
      value = source.slice(node.sourceSpan.start.offset, node.sourceSpan.end.offset)
    }
    return { type: 'HTMLText', value }
  }
  if (node.kind === 'comment') {
    return { type: 'HTMLComment', value: node.value ?? '' }
  }
  if (node.kind === 'docType') {
    // angular-html-parser exposes `value` as just the doctype identifier
    // (e.g. "html"), dropping the `DOCTYPE` keyword. Recover the full
    // original source so we round-trip exactly.
    let raw = `DOCTYPE ${node.value ?? 'html'}`
    if (node.sourceSpan) {
      const orig = source.slice(node.sourceSpan.start.offset, node.sourceSpan.end.offset)
      const m = /^<!([\s\S]+)>$/.exec(orig)
      if (m) raw = m[1]
    }
    return { type: 'HTMLDoctype', value: raw }
  }
  if (node.kind === 'element') {
    // angular-html-parser prefixes namespaced elements (svg, MathML) with
    // `:svg:` / `:math:` to mark the namespace. The author wrote
    // `<svg>` / `<path>` in the source — recover the original name from
    // nameSpan so round-tripping preserves it.
    let name = node.name
    if (node.nameSpan) {
      const orig = source.slice(node.nameSpan.start.offset, node.nameSpan.end.offset)
      if (orig.length > 0) name = orig
    }
    return {
      type: 'HTMLElement',
      name,
      attrs: node.attrs.map((a) => {
        // angular-html-parser normalises some attribute names (strips the
        // `:` directive prefix). Recover the original from the keySpan so
        // round-tripping preserves the source.
        let name = a.name
        if (a.keySpan) {
          const orig = source.slice(a.keySpan.start.offset, a.keySpan.end.offset)
          if (orig.length > 0) name = orig
        }
        // Recover the original quote character (used by
        // edgeAttributeQuotes: "preserve"). angular-html-parser's
        // valueSpan includes the surrounding quotes, so the first byte
        // of the span IS the opening quote (or the first content char
        // for unquoted values).
        let valueQuote = null
        if (a.valueSpan) {
          const ch = source[a.valueSpan.start.offset]
          if (ch === '"' || ch === "'") valueQuote = ch
        }
        // Boolean attributes (no `=` in source) have no valueSpan; emit
        // them as { value: null } so the printer outputs just the name.
        const hasValue = a.valueSpan !== undefined && a.valueSpan !== null
        // Recover the raw (entity-encoded) value from the source span so
        // we round-trip `&amp;` etc. valueSpan covers the value including
        // surrounding quotes — strip those.
        let value = null
        if (hasValue) {
          const raw = source.slice(a.valueSpan.start.offset, a.valueSpan.end.offset)
          if (valueQuote && raw.startsWith(valueQuote) && raw.endsWith(valueQuote)) {
            value = raw.slice(1, -1)
          } else {
            value = raw
          }
        }
        return {
          name,
          value,
          valueQuote,
        }
      }),
      children: node.children.map((c) => convertNode(c, source)),
      isSelfClosing: !!node.isSelfClosing,
      isVoid: !!node.isVoid,
    }
  }
  return { type: 'HTMLText', value: '' }
}
